changes.find:
var picked :| picked in values;
value := picked;
var rest := values - {picked};
if rest != {} {
  var other := Least(rest);
  if other < value {
    value := other;
  }
}
forall other | other in values
  ensures value <= other
{
  if other != picked {
    assert other in rest;
  }
}

changes.replace:
var picked :| picked in values;
var rest := values - {picked};
if rest == {} {
  value := picked;
  forall other | other in values
    ensures value <= other
  {
    assert other !in rest;
  }
} else {
  var smallest := Least(rest);
  value := if smallest < picked then smallest else picked;
  forall other | other in values
    ensures value <= other
  {
    if other != picked {
      assert other in rest;
    }
  }
}
